select subject, ref, status from issue_state_at('mariadb', TIMESTAMP '2016-10-31 02:09') where ref='MXS-845';
select rel, count(*) from relations_at('mariadb', TIMESTAMP '2016-10-31 02:09') group by rel;
select * from entities where id like '%845' limit 5;

with e as (
 select *, row_number() over (partition by type, issue_key, occurred_at order by recorded_at desc, id desc) rn
 from events
 where type in ('issue.created','issue.status_changed') and recorded_at <= TIMESTAMP '2018-12-23 21:49' and occurred_at <= TIMESTAMP '2018-12-20 19:22'
), l as (
 select issue_key, payload->>'status' status, occurred_at,
  row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r2
 from e where rn=1 and (type='issue.status_changed' or payload->>'project'='INDY')
)
select count(*) from l where r2=1 and status='Code Review'

with ev as (
 select *, row_number() over (partition by type, issue_key, occurred_at order by recorded_at desc, id desc) rn
 from events where recorded_at <= TIMESTAMP '2019-02-19 10:00' and occurred_at <= TIMESTAMP '2019-02-18 17:50'
   and type in ('issue.created','issue.status_changed')
), cur as (
 select issue_key, occurred_at, id, payload->>'status' status, payload->>'project' proj, type from ev where rn=1
), last as (
 select issue_key, status, row_number() over (partition by issue_key order by occurred_at desc, case when type='issue.created' then 0 else 1 end desc, id desc) r from cur
), proj as (select distinct issue_key from cur where proj='INDY')
select status, count(*) from last where r=1 and issue_key in (select issue_key from proj) group by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' status, type
 from events where type in ('issue.created','issue.status_changed') and recorded_at <= TIMESTAMP '2018-06-13 03:00' and occurred_at <= TIMESTAMP '2018-06-12 17:48'
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc, ) = 1
), last as (
 select * from dedup qualify row_number() over (partition by issue_key order by occurred_at desc, case when type='issue.created' then 0 else 1 end desc) = 1
)
select count(*), count(distinct issue_key) from last where status='To Do'

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' status, type
 from events where type in ('issue.created','issue.status_changed') and recorded_at <= TIMESTAMP '2018-06-13 03:00' and occurred_at <= TIMESTAMP '2018-06-12 17:48'
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc) = 1
