)
select * from last where status='To Do'

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s, id from events where type in ('issue.created','issue.status_changed')
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at order by recorded_at desc, id desc)=1
), st as (
 select issue_key, ts, (select s from dedup d where d.issue_key=k.issue_key and d.occurred_at<=ts order by occurred_at desc limit 1) s
 from (select distinct issue_key from dedup) k, (select TIMESTAMP '2020-01-13 18:25' ts union all select TIMESTAMP '2020-03-30 10:39') t
)
select issue_key from st where s in ('Code Review','Customer Validation','Design','In Progress','To Test')
group by issue_key having count(*)=2 order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' status, type
 from events where type in ('issue.created','issue.status_changed')
),
dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc)=1
),
st as (
 select issue_key, (select status from dedup d where d.issue_key=i.issue_key and d.occurred_at<=t order by occurred_at desc, case when type='issue.status_changed' then 1 else 0 end desc limit 1) s, t
 from (select distinct issue_key from dedup) i, (values (TIMESTAMP '2017-06-03 09:14'),(TIMESTAMP '2017-07-09 00:31')) v(t)
)
select issue_key from st where s in ('Code Review','Customer Validation','Design','In Progress','To Test')
group by issue_key having count(*)=2 order by issue_key

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' status, type from events where type in ('issue.created','issue.status_changed')
), dedup as (
 select * from (select *, row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc) rn from ev) where rn=1
), st as (
 select issue_key, status, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r from dedup where occurred_at <= TIMESTAMP '2017-08-04 23:54'
), st2 as (
 select issue_key, status, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r from dedup where occurred_at <= TIMESTAMP '2017-10-28 05:46'
)
select a.issue_key, a.status, b.status from st a join st2 b on a.issue_key=b.issue_key and a.r=1 and b.r=1
where a.status in ('Code Review','Customer Validation','Design','In Progress','To Test') and b.status in ('Code Review','Customer Validation','Design','In Progress','To Test') order by 1

