), d as (select * from dedup where rn=1),
st as (
 select issue_key, ts, (select arg_max(st, (occurred_at, k, recorded_at)) from d d2 where d2.issue_key=i.issue_key and d2.occurred_at<=ts) s
 from (select distinct issue_key from d) i, (values (TIMESTAMP '2020-12-06 07:17'),(TIMESTAMP '2021-01-30 16:46')) t(ts)
)
