 select issue_key, occurred_at, payload->>'status' s, recorded_at,
  row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc) rn
 from events where type in ('issue.status_changed','issue.created') and payload->>'status' is not null
), e as (select * from ev where rn=1),
st as (
 select k, (select s from e where e.issue_key=k and occurred_at<=t order by occurred_at desc limit 1) s
 from (select distinct issue_key k from e) , (select TIMESTAMP '2012-05-06 08:17' t union all select TIMESTAMP '2012-07-15 21:37') 
)
select k from (select k, count(*) n, count(distinct t) from (
 select k, t, (select s from e where e.issue_key=k and occurred_at<=t order by occurred_at desc limit 1) s
 from (select distinct issue_key k from e), (select TIMESTAMP '2012-05-06 08:17' t union all select TIMESTAMP '2012-07-15 21:37')
) where s='In Progress' group by k) where n=2 order by k

with ev as (
 select issue_key, occurred_at, recorded_at, type, payload->>'status' st, 
  row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc) rn
 from events where type in ('issue.status_changed','issue.created')
), cur as (
 select issue_key, occurred_at, coalesce(st, null) st, type from ev where rn=1
), s as (
 select issue_key, type, occurred_at, case when type='issue.created' then (select payload->>'status' from events e where e.id is not null and e.issue_key=cur.issue_key and e.type='issue.created' limit 1) else st end st from cur
), at1 as (
 select issue_key, arg_max(st, occurred_at) st from s where occurred_at<=TIMESTAMP '2012-05-03 17:42' group by issue_key
), at2 as (
 select issue_key, arg_max(st, occurred_at) st from s where occurred_at<=TIMESTAMP '2012-06-17 04:42' group by issue_key
)
select a.issue_key, a.st, b.st from at1 a join at2 b using(issue_key) where a.st='In Progress' and b.st='In Progress' and a.issue_key like 'RAVE-%'

