 from (select distinct issue_key from dedup) k, (select TIMESTAMP '2012-09-17 04:51' t union all select TIMESTAMP '2012-11-08 05:34') ts
)
select issue_key from st group by issue_key having count(*) filter (where s='In Progress')=2 order by 1

